def run(context):
    # Extract relevant signal log data
    signals = context['signal_log']

    # Calculate outcome summaries
    outcome_summary = {'success_count': 0, 'failure_count': 0}
    for signal in signals:
        if signal['hit_target']:
            outcome_summary['success_count'] += 1
        elif signal['hit_stop']:
            outcome_summary['failure_count'] += 1

    return outcome_summary
